            how_p1: 'வினாடிகளில் பதிவு செய்யுங்கள். உங்கள் பாத்திரத்தை தேர்வு செய்யுங்கள் — ஹோஸ்ட் அல்லது வாடகைதாரர். முதல் 999 பட்டியல்கள் இலவசம்!',
            how_step2: 'படி 2',
            how_title2: 'பட்டியலிடுங்கள் அல்லது தேடுங்கள்',
            how_p2: 'ஹோஸ்ட்கள் புகைப்படங்களுடன் சொத்துக்களை சேர்க்கிறார்கள். வாடகைதாரர்கள் வடிகட்டிகளுடன் தேடுகிறார்கள்.',
            how_step3: 'படி 3',
            how_title3: 'அன்லாக் & இணைக்கவும்',
            how_p3: 'வாடகைதாரர்கள் இப்போது முழு முகவரி மற்றும் தொலைபேசியை இலவசமாக அன்லாக் செய்யலாம்.',

            feat_chip: '⚡ அம்சங்கள்',
            feat_h2: 'உங்களுக்கு தேவையான அனைத்தும்',
            feat_p: 'நவீன இந்திய வாடகைதாரர் மற்றும் ஹோஸ்ட்டுக்காக கட்டமைக்கப்பட்ட முழுமையான வாடகை தளம்.',
            feat1_title: 'இலவச வீட்டு பட்டியல்',
            feat1_p: 'உங்கள் சொத்தை இலவசமாக பட்டியலிடுங்கள் — முதல் 999 பட்டியல்களை பூஜ்ஜிய கட்டணத்துடன் கொண்டாடுகிறோம்!',
            feat2_title: 'GPS இடம் தானியங்கி நிரப்பு',
            feat2_p: 'பகுதி, நகரம் மற்றும் மாநிலத்தை நிரப்ப உங்கள் சாதன GPS ஐ பயன்படுத்துங்கள்.',
            feat3_title: '5 வரை புகைப்படங்கள்',
            feat3_p: 'உங்கள் சொத்தை காட்டும் உயர்தர படங்களை பதிவேற்றுங்கள்.',
            feat4_title: 'பகுப்பாய்வு டாஷ்போர்டு',
            feat4_p: 'காட்சி விளக்கப்படங்களுடன் பட்டியல்கள் மற்றும் செயல்பாட்டை கண்காணியுங்கள்.',
            feat5_title: 'கிரெடிட் அன்லாக் அமைப்பு',
            feat5_p: 'புதிய பயனர்களுக்கு 10 இலவச கிரெடிட்கள் கிடைக்கும்.',

            testi_chip: '💬 மதிப்புரைகள்',
            testi_h2: 'எங்கள் ஹோஸ்ட்கள் என்ன சொல்கிறார்கள்',
            testi1_text: '"5 நிமிடங்களில் என் அபார்ட்மெண்டை பட்டியலிட்டேன். மணிக்கணக்கில் தீவிர விசாரணைகள் வந்தன!"',
            testi1_name: 'ரோஹித் ஷர்மா',
            testi1_role: 'ஹோஸ்ட் · மும்பை',
            testi2_text: '"GPS தானியங்கி நிரப்பு பட்டியலை மிகவும் எளிதாக்கியது. டாஷ்போர்டு பகுப்பாய்வு சிறந்த நுண்ணறிவை தருகிறது."',
            testi2_name: 'பிரியா நாயர்',
            testi2_role: 'ஹோஸ்ட் · பெங்களூரு',
            testi3_text: '"Rent Nivas என் பட்டியல்களில் முழு கட்டுப்பாட்டை தந்தது. பல சொத்துக்களை நிர்வகிப்பது தடையற்றது."',
            testi3_name: 'அங்கிட் மேத்தா',
            testi3_role: 'ஹோஸ்ட் · ஹைதராபாத்',

            cta_h2: 'உங்கள் சரியான வீட்டை கண்டுபிடிக்க தயாரா?',
            cta_p: 'Rent Nivas இல் சேருங்கள் — இந்தியாவின் எளிய வாடகை தளம். முதல் 999 பட்டியல்கள் இலவசம்!',
            cta_btn1: '🏠 தொடங்குங்கள்',
