            "feat4_p": "വിഷ്വൽ ചാർട്ടുകളിലൂടെ ലിസ്റ്റിംഗ്, വില വിതരണം, പ്രവർത്തനം ട്രാക്ക് ചെയ്യുക.",
            "feat5_title": "ക്രെഡിറ്റ് അൺലോക്ക് സിസ്റ്റം",
            "feat5_p": "പുതിയ ഉപയോക്താക്കൾക്ക് 10 സൗജന്യ അൺലോക്ക് ക്രെഡിറ്റുകൾ ലഭിക്കും, പേയ്‌മെന്റ് നിഷ്ക്രിയമായിരിക്കുമ്പോൾ കോൺടാക്റ്റ് അൺലോക്ക് സൗജന്യമാണ്.",
            "testi_chip": "💬 അഭിപ്രായങ്ങൾ",
            "testi_h2": "ഞങ്ങളുടെ ഹോസ്റ്റുകൾ പറയുന്നത്",
            "testi1_text": "\"5 മിനിറ്റിൽ എന്റെ അപാർട്ട്മെന്റ് ലിസ്റ്റ് ചെയ്തു. മണിക്കൂറുകൾക്കുള്ളിൽ ഗൗരവമായ അന്വേഷണങ്ങൾ ലഭിച്ചു!\"",
            "testi1_name": "റോഹിത് ശർമ്മ",
            "testi1_role": "ഹോസ്റ്റ് · മുംബൈ",
            "testi2_text": "\"GPS ഓട്ടോ-ഫിൽ ലിസ്റ്റിംഗ് വളരെ എളുപ്പമാക്കി. ഡാഷ്ബോർഡ് അനാലിറ്റിക്സ് മികച്ച വിവരങ്ങൾ നൽകുന്നു.\"",
            "testi2_name": "പ്രിയ നായർ",
            "testi2_role": "ഹോസ്റ്റ് · ബെംഗളൂരു",
            "testi3_text": "\"Rent Nivas എന്റെ ലിസ്റ്റിംഗുകളിൽ പൂർണ്ണ നിയന്ത്രണം നൽകി. ഒന്നിലധികം പ്രോപ്പർട്ടികൾ കൈകാര്യം ചെയ്യുന്നത് എളുപ്പമാണ്.\"",
            "testi3_name": "അങ്കിത് മേത്ത",
            "testi3_role": "ഹോസ്റ്റ് · ഹൈദരാബാദ്",
            "cta_h2": "നിങ്ങളുടെ സരിയായ വീട് കണ്ടെത്താൻ തയ്യാറാണോ?",
